   207→/* ============================================
   208→   UTILITY CLASSES - Design System
   209→   ============================================ */
   210→
   211→@layer utils {
   212→  /* Glass Morphism */
   213→  .glass {
   214→    background: var(--glass-bg);
   215→    backdrop-filter: blur(20px);
   216→    -webkit-backdrop-filter: blur(20px);
   217→    border: 1px solid var(--glass-border);
   218→  }
   219→
   220→  .glass-elevated {
   221→    background: var(--glass-bg-elevated);
   222→    backdrop-filter: blur(24px);
   223→    -webkit-backdrop-filter: blur(24px);
   224→    border: 1px solid var(--border-glass);
   225→  }
   226→
   227→  .glass-card {
   228→    background: var(--glass-bg);
   229→    backdrop-filter: blur(20px);
   230→    -webkit-backdrop-filter: blur(20px);
   231→    border: 1px solid var(--glass-border);
   232→    border-radius: 1.5rem;
   233→  }
   234→
   235→  /* Grain Texture */
   236→  .grain {
   237→    position: relative;
   238→  }
   239→  .grain::before {
   240→    content: "";
   241→    position: absolute;
   242→    inset: 0;
   243→    background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.65' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)'/%3E%3C/svg%3E");
   244→    opacity: 0.03;
   245→    pointer-events: none;
   246→    z-index: 1;
   247→  }
   248→
   249→  /* Mesh Gradients */
   250→  .mesh-gradient {
   251→    background: radial-gradient(
   252→        ellipse at 20% 20%,
   253→        var(--glow-accent) 0%,
   254→        transparent 50%
   255→      ),
   256→      radial-gradient(
   257→        ellipse at 80% 80%,
   258→        var(--glow-highlight) 0%,
   259→        transparent 50%
   260→      ),
   261→      var(--brand-deep);
   262→  }
   263→
   264→  .mesh-gradient-subtle {
   265→    background: radial-gradient(
   266→        ellipse at 10% 10%,
   267→        rgba(52, 211, 153, 0.08) 0%,
   268→        transparent 40%
   269→      ),
   270→      radial-gradient(
   271→        ellipse at 90% 90%,
   272→        rgba(99, 102, 241, 0.08) 0%,
   273→        transparent 40%
   274→      ),
   275→      var(--brand-deep);
   276→  }
   277→
   278→  .mesh-gradient-hero {
   279→    background: radial-gradient(
   280→        ellipse at 30% 0%,
   281→        rgba(52, 211, 153, 0.2) 0%,
   282→        transparent 50%
   283→      ),
   284→      radial-gradient(
   285→        ellipse at 70% 100%,
   286→        rgba(99, 102, 241, 0.2) 0%,
   287→        transparent 50%
   288→      ),
   289→      radial-gradient(ellipse at 50% 50%, rgba(99, 102, 241, 0.05) 0%, transparent 70%),
   290→      var(--brand-deep);
   291→  }
   292→
   293→  /* Hyper Border (Gradient animated border) */
   294→  .hyper-border {
   295→    position: relative;
   296→    background: var(--brand-surface);
   297→    border-radius: 1.5rem;
   298→  }
   299→  .hyper-border::before {
   300→    content: "";
   301→    position: absolute;
   302→    inset: -1px;
   303→    border-radius: inherit;
   304→    padding: 1px;
   305→    background: linear-gradient(
   306→      135deg,
   307→      var(--brand-accent),
   308→      var(--brand-highlight),
   309→      var(--brand-accent)
   310→    );
   311→    background-size: 200% 200%;
   312→    -webkit-mask:
   313→      linear-gradient(#fff 0 0) content-box,
   314→      linear-gradient(#fff 0 0);
   315→    -webkit-mask-composite: xor;
   316→    mask-composite: exclude;
   317→    animation: border-gradient 3s ease infinite;
   318→    pointer-events: none;
   319→  }
   320→
   321→  /* Glow Effects */
   322→  .glow-accent {
   323→    box-shadow:
   324→      0 0 20px var(--glow-accent),
   325→      0 0 40px var(--glow-accent);
   326→  }
   327→
   328→  .glow-highlight {
   329→    box-shadow:
   330→      0 0 20px var(--glow-highlight),
   331→      0 0 40px var(--glow-highlight);
   332→  }
   333→
   334→  .hover-glow-accent {
   335→    transition: box-shadow 0.3s ease;
   336→  }
   337→  .hover-glow-accent:hover {
   338→    box-shadow:
   339→      0 0 20px var(--glow-accent),
   340→      0 0 40px var(--glow-accent);
   341→  }
   342→
   343→  .hover-glow-highlight {
   344→    transition: box-shadow 0.3s ease;
   345→  }
   346→  .hover-glow-highlight:hover {
   347→    box-shadow:
   348→      0 0 20px var(--glow-highlight),
   349→      0 0 40px var(--glow-highlight);
   350→  }
   351→
   352→  /* Text Gradients */
   353→  .text-gradient {
   354→    @apply bg-clip-text text-transparent;
   355→  }
   356→
   357→  .text-gradient-accent {
   358→    background: linear-gradient(135deg, var(--brand-accent), #6ee7b7);
   359→    -webkit-background-clip: text;
   360→    background-clip: text;
   361→    color: transparent;
   362→  }
   363→
   364→  .text-gradient-highlight {
   365→    background: linear-gradient(135deg, var(--brand-highlight), #a5b4fc);
   366→    -webkit-background-clip: text;
   367→    background-clip: text;
   368→    color: transparent;
   369→  }
   370→
   371→  .text-gradient-brand {
   372→    background: linear-gradient(
   373→      135deg,
   374→      var(--brand-accent),
   375→      var(--brand-highlight)
   376→    );
   377→    -webkit-background-clip: text;
   378→    background-clip: text;
   379→    color: transparent;
   380→  }
   381→
   382→  /* Card Hover Effects */
   383→  .card-hover {
   384→    transition:
   385→      transform 0.3s ease,
   386→      box-shadow 0.3s ease;
   387→  }
   388→  .card-hover:hover {
   389→    transform: translateY(-4px);
   390→    box-shadow:
   391→      0 20px 40px rgba(0, 0, 0, 0.3),
   392→      0 0 40px var(--glow-accent);
   393→  }
   394→
   395→  /* Shimmer Effect */
   396→  .shimmer {
   397→    background: linear-gradient(
   398→      90deg,
   399→      transparent 0%,
   400→      rgba(255, 255, 255, 0.05) 50%,
   401→      transparent 100%
   402→    );
   403→    background-size: 200% 100%;
   404→    animation: shimmer 2s linear infinite;
   405→  }
   406→
   407→  /* Grid Background */
   408→  .bg-grid {
   409→    --bg-grid-color: rgba(255, 255, 255, 0.03);
   410→    background-color: transparent;
   411→    background-image: linear-gradient(
   412→        90deg,
   413→        var(--bg-grid-color) 1px,
   414→        transparent 1px
   415→      ),
   416→      linear-gradient(180deg, var(--bg-grid-color) 1px, transparent 1px);
   417→    background-size: 64px 64px;
   418→  }
   419→
   420→  .bg-grid-small {
   421→    --bg-grid-color: rgba(255, 255, 255, 0.02);
   422→    background-color: transparent;
   423→    background-image: linear-gradient(
   424→        90deg,
   425→        var(--bg-grid-color) 1px,
   426→        transparent 1px
   427→      ),
   428→      linear-gradient(180deg, var(--bg-grid-color) 1px, transparent 1px);
   429→    background-size: 24px 24px;
   430→  }
   431→
   432→  /* Dot Pattern */
   433→  .dot-pattern {
   434→    --dot-color: rgba(255, 255, 255, 0.1);
   435→    --dot-background: transparent;
   436→    opacity: 0.8;
   437→    background-image: radial-gradient(
   438→      var(--dot-color) 0.5px,
   439→      var(--dot-background) 0.5px
   440→    );
   441→    background-size: var(--size, 10px) var(--size, 10px);
   442→  }
   443→
   444→  /* Scanline Effect */
   445→  .scanline {
   446→    position: relative;
   447→    overflow: hidden;
   448→  }
   449→  .scanline::after {
   450→    content: "";
   451→    position: absolute;
   452→    inset: 0;
   453→    background: linear-gradient(
   454→      90deg,
   455→      transparent,
   456→      rgba(52, 211, 153, 0.1),
   457→      transparent
   458→    );
   459→    animation: scanline 3s ease-in-out infinite;
   460→    pointer-events: none;
   461→  }
   462→
   463→  /* Focus ring for dark theme */
   464→  .focus-ring {
   465→    @apply focus-visible:ring-2 focus-visible:ring-primary focus-visible:ring-offset-2 focus-visible:ring-offset-background outline-none;
   466→  }
   467→}
   468→
   469→/* ============================================
   470→   COMPONENT STYLES
   471→   ============================================ */
   472→
   473→/* Citation */
   474→.citation {
   475→  position: relative;
   476→  display: inline-block;
   477→  padding: 4px;
   478→  border-radius: 0.5rem;
   479→  color: var(--foreground);
   480→  font-style: italic;
   481→  --gap: -16px;
   482→}
   483→
   484→.citation::before {
   485→  content: "\201C";
   486→  font-size: 3rem;
   487→  position: absolute;
   488→  top: -12px;
   489→  left: -12px;
   490→  line-height: 1;
   491→  color: var(--brand-accent);
   492→}
   493→
   494→.citation::after {
   495→  content: "\201D";
   496→  font-size: 3rem;
   497→  position: absolute;
   498→  bottom: -16px;
   499→  right: -4px;
   500→  line-height: 1;
   501→  color: var(--brand-accent);
   502→}
   503→
   504→.citation strong {
   505→  font-weight: 700;
   506→  background: rgba(52, 211, 153, 0.2);
   507→  display: inline;
   508→  padding: 2px;
   509→  margin: -2px;
   510→}
   511→
   512→/* Prose (Typography) */
   513→.prose {
   514→  scroll-margin-top: 40px;
   515→
   516→  & h1,
   517→  & h2,
   518→  & h3,
   519→  & h4,
   520→  & h5,
   521→  & h6 {
   522→    position: relative;
   523→    scroll-margin-top: 70px;
   524→
   525→    &:hover {
   526→      & .icon-link {
   527→        opacity: 1;
   528→      }
   529→    }
   530→  }
   531→
   532→  & .icon.icon-link {
   533→    width: 20px;
   534→    height: 100%;
   535→    display: block;
   536→    position: absolute;
   537→    display: flex;
   538→    align-items: center;
   539→    justify-content: center;
   540→    left: -24px;
   541→    opacity: 0;
   542→    transition: opacity 0.2s ease;
   543→
   544→    &::before {
   545→      content: "#";
   546→      font-size: 1.5rem;
   547→      color: var(--brand-accent);
   548→    }
   549→  }
   550→}
   551→
   552→/* Scrollbar styling for dark theme */
   553→::-webkit-scrollbar {
   554→  width: 8px;
   555→  height: 8px;
   556→}
   557→
   558→::-webkit-scrollbar-track {
   559→  background: var(--brand-deep);
   560→}
   561→
   562→::-webkit-scrollbar-thumb {
   563→  background: var(--brand-elevated);
   564→  border-radius: 4px;
   565→}
   566→
   567→::-webkit-scrollbar-thumb:hover {
   568→  background: var(--text-muted);
   569→}
   570→
   571→/* Selection */
   572→::selection {
   573→  background: rgba(52, 211, 153, 0.3);
   574→  color: var(--text-primary);
   575→}
